def Independent (D : Type) (ops : List (D → D)) : Prop :=
  ∀ (i : Nat) (h : i < ops.length),
    ∃ (d : D), (ops.get ⟨i, h⟩) d ≠ d

def Determined (D : Type) (ops : List (D → D)) (determined : D → Prop) : Prop :=
  ∀ (d : D), determined d ↔
    (∀ (op : D → D), op ∈ ops → op d = d)

def Symmetric (D : Type) (ops : List (D → D)) (determined : D → Prop) : Prop :=
  ∀ (d : D) (op : D → D), op ∈ ops →
    (determined d ↔ determined (op d))

def Exhaustive (D : Type) (ops : List (D → D)) (determined : D → Prop) : Prop :=
  ∀ (op : D → D),
    (∀ (d : D), determined d ↔ determined (op d)) → op ∈ ops

def conservation (S : SIDESystem) : Prop :=
  ∀ (d : S.domain) (op : S.domain → S.domain),
    op ∈ S.ops → (S.determined d ↔ S.determined (op d))

